  "data_meaning": {
    "inputs": [
      {"text": "Исходные данные о пласте, известные с недостаточной точностью.", "claims": ["c1"], "hypothesis": false}
    ],
    "outputs": [
      {"text": "Простое приближённое решение вместо точного. Его достаточно, когда нужна общая картина.", "claims": ["c1"], "hypothesis": false}
    ],
    "breaks": [
      {"text": "Вблизи скважины, где решение имеет известные особенности, простое приближение может быть неверным.", "claims": [], "hypothesis": true}
    ]
  },
  "it_analogy": {
    "pack_id": null,
    "analogy": "Оценка ёмкости по агрегированным метрикам вместо трассировки каждого запроса: при грубых входных данных точный расчёт не даёт выигрыша.",
    "breaks_where": "В ИТ агрегаты часто можно пересчитать из логов. О пласте данных мало, и «логов» по каждой точке нет.",
    "hypothesis": true
  },
  "now_nuance": {
    "text": "Сегодня такие задачи часто решают численно, на расчётной сетке в программных симуляторах. Простые формулы остаются для быстрой оценки.",
    "hypothesis": true
  },
  "threshold": {
    "is_threshold": true,
    "why": "Простое приближение — не брак, а осознанный выбор при неточных данных. Без этого непонятно, зачем нужны приближённые методы главы."
  },
